// th15_s3_w01 — st03.ecl.txt MainSub00 (1206-1254) + ECir00/ECir00_at
// 四排 ECir00 横排编队，每排 10 只、间隔 10 帧；每敌 4 路十字环自机狙，按 rank 计数与间隔。
const TIME_LIMIT: int = 1324;
const OPENING_BUFFER: int = 120;

// 源 etSprite(0, 4, 6)：TH15 type4 -> TH15_BALL 槽（见 bullet-types.md）
const TH15_BALL: int = 416;
const BULLET_COLOR: int = 6;
const ENEMY_HP: int = 100;

// 源 ECir00_at: wait(10) -> etCount(0,4,1) -> 每 volley 一次 RANDF2 偏角 + ANGLE_PLAYER
// diffI($B,1,2,4,20)；间隔 E/N=70、H=30、L=10；速度 1.5/2.5/3.5/4.5；
// 偏角幅度 E=1deg，其余=10deg（RANDF2 双向）。
async sub fire_volleys() {
    wait(10);
    var rank: int = global(GVAR_RANK);
    var volleys: int = 1;
    var interval: int = 70;
    var speed: fx = 1.5fx;
    var spread: int = 182;
    if rank == 1 { volleys = 2; speed = 2.5fx; spread = 1820; }
    if rank == 2 { volleys = 4; interval = 30; speed = 3.5fx; spread = 1820; }
    if rank >= 3 { volleys = 20; interval = 10; speed = 4.5fx; spread = 1820; }
    for i in 0..volleys {
        var px: fx = $self_x;
        var py: fx = $self_y;
        // 源 ANGLE_PLAYER 每个 volley 读一次，4 路共享；RANDF2 也每 volley 抽一次
        var base: angle = atan2($player_y - py, $player_x - px)
                          + ((rand(2 * spread + 1) - spread) as angle);
        for k in 0..4 {
            var a: angle = base + ((k * 16384) as angle);
            // 源 etEx(0,0,2,1,...) 为出生 ANIM：进入时 position -= 4 * velocity
            _ = fire(TH15_BALL, BULLET_COLOR,
                     px - 4fx * speed * cos(a),
                     py - 4fx * speed * sin(a),
                     speed, a, none, none);
        }
        wait(interval);
    }
}

// 源 ECir00：REL 随机偏移 ±16（RANDF2*16 两次独立抽样）-> 60 帧 mode1 收回 0；
// 60 帧后清 flagSet(15)；120 帧时朝 (F0,F1) 定角，速度 0 线性加速到 3（120 帧）。
async sub source_enemy(base_x: fx, base_y: fx, target_x: fx, target_y: fx) {
    set_invuln(65535);
    set_hurtbox(12fx);        // 源 setHurtbox(24,24) 普通圆分支取半径 12
    set_hitbox(8fx);          // 源 setHitbox(16,16) 半径 8
    set_enemy_flag(ENEMY_NO_BODY, 1);
    move_to(60, base_x, base_y, EASE_QUAD_IN);
    wait(60);
    set_enemy_flag(ENEMY_NO_BODY, 0);
    spawn fire_volleys();
    wait(60);
    // 源 getAngle(%F2, FINAL_X, FINAL_Y, %F0, %F1) -> moveVel(%F2, 0) + moveSpeedTime(120,0,3)
    var dir: angle = atan2(target_y - $self_y, target_x - $self_x);
    move_vel(0, dir, 0fx, EASE_LINEAR);
    move_speed(120, 3fx, EASE_LINEAR);
    loop { wait(1000); }
}

// 源 enmCreate("ECir00", %A, y, 100, 1000, 1)：每排 10 只、x 每只 ±40、间隔 10 帧
sub spawn_row(start_x: fx, y: fx, step: fx, target_x: fx, target_y: fx) {
    var x: fx = start_x;
    for i in 0..10 {
        var ox: fx = (rand(65537) - 32768) as fx / 2048fx;   // RANDF2*16，独立抽样
        var oy: fx = (rand(65537) - 32768) as fx / 2048fx;
        _ = spawn_enemy(x + ox, y + oy, ENEMY_HP, 0, 1000, 0,
                        source_enemy(x, y, target_x, target_y));
        x = x + step;
        wait(10);
    }
}

// 源 MainSub00 四段：F0/F1 依次 (-64,320)、(64,320)、(0,320)、(0,320)
async sub pattern() {
    wait(OPENING_BUFFER);
    spawn_row(180fx, 64fx, -40fx, -64fx, 320fx);
    spawn_row(-180fx, 140fx, 40fx, 64fx, 320fx);
    spawn_row(180fx, 180fx, -40fx, 0fx, 320fx);
    spawn_row(-180fx, 120fx, 40fx, 0fx, 320fx);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
